    "image_url": "https://beehiiv-images-production.s3.amazonaws.com/uploads/asset/file/03c0a9bd-5c93-4027-95ee-b86fee11eaaa/Newsletter_Images.jpg?t=1787018807",
    "author": "AIRA",
    "author_avatar": "assets/logo.jpg",
